We say that $X_t$ has $(\eta, b)$-exponential local polarization 
	if it satisfies local polarization (1.2) and the following additional property
	\begin{enumerate}
		\item {\bf(Strong suction at the low end):} There exists $\tau > 0$ such that if $X_j \leq \tau$ then
		$\Pr[X_{j+1} \leq X_j^{b} | X_j] \geq \eta$.
	\end{enumerate}

We say that a matrix $M \in \mathbb{F}_q^{k\times k}$ satisfies matrix polarization, if and only if for every pair of random variables $({\boldsymbol{U}}, W)$, such that  ${\boldsymbol{U}} = ({\boldsymbol{U}}_1,\dots,{\boldsymbol{U}}_k) \in \mathbb{F}_q^k$, $W = (W_1,\ldots,W_k)$ is supported on some finite set, and the pairs  $({\boldsymbol{U}}_i,W_i)$ are independently and identically distributed for $i \in [k]$, the vector ${\boldsymbol{V}} := {\boldsymbol{U}} \cdot M$ satisfies the following conditions:
	\begin{enumerate}
		\item
		{\bf (Variance in the middle):}
		There is some index $j \in [k]$
		for which the following holds:
		For every $\tau > 0$, there exists $\varepsilon=\varepsilon(\tau) > 0$ such that
		if $\overline{H}({\boldsymbol{U}}_1 | W) \in (\tau, 1-\tau)$,
		then
		$$\overline{H}(({\boldsymbol{V}})_j | {\boldsymbol{V}}_{< j}, W)  \geq \overline{H}({\boldsymbol{U}}_1 | W) + \varepsilon.$$

		\item
		{\bf (Suction at the lower end):}
		There is some index $j \in [k]$
		for which the following holds:

		For every $c < \infty$, there  exists $\tau > 0$ such that
		if
		$\overline{H}({\boldsymbol{U}}_1 | W) < \tau$
		then
		$$\overline{H}({\boldsymbol{V}}_j | {\boldsymbol{V}}_{< j}, W)  \leq \frac{1}{c}~\overline{H}({\boldsymbol{U}}_1 | W).$$


		\item
		{\bf (Suction at the high end):}
		Analogously to suction at the low end, there is some index $j \in [k]$
		for which the following holds:

		For every $c < \infty$, there  exists $\tau > 0$ such that
		if
		$\overline{H}({\boldsymbol{U}}_1 | W) > 1-\tau$
		then
		$$1 - \overline{H}({\boldsymbol{V}}_j | {\boldsymbol{V}}_{< j}, W)
		\leq \frac{1}{c}(1-\overline{H}({\boldsymbol{U}}_1 | W)).$$
	\end{enumerate}
	Additionally, we say that $M$ satisfies $(\eta,b)$-exponential matrix polarization if we have the following property:
	\begin{enumerate}
		\item[2'.] {\bf (Strong Suction at the lower end):}
		There  exists $\tau > 0$ such that
		if
		$\overline{H}({\boldsymbol{U}}_1 | W) < \tau$ then for at least $\eta$ fraction of the indices $j \in [k]$ we have: 
		then
		$$\overline{H}({\boldsymbol{V}}_j | {\boldsymbol{V}}_{< j}, W)  \leq \overline{H}({\boldsymbol{U}}_1 | W)^b .$$
	\end{enumerate}
